arguments.new_string:
@staticmethod
    def _validate_brace_structure(fmt):
        """Validate braces in format string are properly paired.
        Uses the same PARSE_RE logic to identify fields and escaped braces,
        then checks that no literal text contains stray braces.
        """
        for part in PARSE_RE.split(fmt):
            if not part:
                continue
            if part[0] == '{' and part[-1] == '}':
                # This is a field matched by PARSE_RE - valid
                continue
            if part == '{{' or part == '}}':
                # These are escaped braces - valid
                continue
            # Literal text - should not contain unescaped braces
            if '{' in part or '}' in part:
                raise ValueError(
                    'Mismatched brace structure in format string'
                )

arguments.old_string:
@staticmethod
    def _validate_brace_structure(fmt):
        """Validate braces in format string are properly paired."""
        depth = 0
        i = 0
        while i < len(fmt):
            if fmt[i:i+2] == '{{':
                i += 2
                continue
            if fmt[i:i+2] == '}}':
                i += 2
                continue
            if fmt[i] == '{':
                depth += 1
            elif fmt[i] == '}':
                depth -= 1
            if depth < 0:
                raise ValueError(
                    'Mismatched brace structure: extraneous closing brace at position %d'
                    % i
                )
            i += 1
        if depth != 0:
            raise ValueError(
                'Mismatched brace structure: format string has %d unclosed brace(s)'
                % depth
            )
